document.addEventListener("publication-catalog-ready",()=>{const topic=document.querySelector('#topic-filter'),query=document.querySelector('#publication-search'),reset=document.querySelector('#reset-publications'),cards=[...document.querySelectorAll('.publication')],years=[...document.querySelectorAll('.publications-page section[id^="year-"]')];function filter(){const value=topic.value,q=query.value.trim().toLocaleLowerCase();let total=0;for(const card of cards){const topics=JSON.parse(card.dataset.topics||'[]');const searchable=[...card.querySelectorAll('h3,.pub-authors,.pub-venue')].map(e=>e.textContent).join(' ').toLocaleLowerCase();const show=(!value||(value==='untagged'?topics.length===0:topics.includes(value)))&&(!q||searchable.includes(q));card.hidden=!show;if(show)total++}for(const year of years){const all=[...year.querySelectorAll('.publication')],n=all.filter(c=>!c.hidden).length;year.hidden=n===0;year.querySelector('.pub-year-heading>span').textContent=n===all.length?n+' publications':n+' of '+all.length+' publications';const link=document.querySelector('.publication-years a[href="#'+year.id+'"]');if(link)link.hidden=n===0}document.querySelector('#no-publications').hidden=total!==0;document.querySelector('#filter-status').textContent=total===cards.length?'Showing all '+total+' publications':'Showing '+total+' of '+cards.length+' publications';}topic.addEventListener('change',filter);query.addEventListener('input',filter);reset.addEventListener('click',()=>{topic.value='';query.value='';filter();topic.focus()});filter()});
